              'sessions_with_file_edits_count': value,
            },
          _ => const <String, dynamic>{},
        },
        'skills_used_count': skillsUsedCount,
        ...switch (writeToolCount) {
          SdkPresent<int?>(value: final value) => {
              'write_tool_count': value,
            },
          _ => const <String, dynamic>{},
        },
      };
}
